import './App.css';
import ReactDOM from 'react-dom';
import Welcome from './components/welcome.jsx';
import Profile from './components/profile.jsx';
import Product from './components/product.jsx';
import Hooks from './components/hooks.jsx';
import ThemeContext from './components/themeContext.jsx';
import ThemeButton from './components/themedButton.jsx';
import Api from './components/api.jsx';


function App() {
  const name = "John";
  const age = 20;
  const city = "New York";
  const country = "USA";
  const email = "john@gmail.com";
  const phone = "1234567890";
  const address = "123 Main St, New York, NY 10001";

  const arr = ["vijay", "kumar", "singh", "raj", "kumar", "vijaytaaa", "vijaijijaji", "vijaytaaa", "vijaijijaji", "vijaytaaa", "vijaijijaji"];
  const namesStartingWithVij = arr.filter((item) => item.startsWith("vij"));

  return (
    <div className="App">
      <header className="App-header">
        <h1>Hello World</h1>
        <p>Name: {name}</p>
        <p>Age: {age}</p>
        <p>City: {city}, Country: {country}</p>
        <p>Email: {email}</p>
        <p>Phone: {phone}</p>
        <p>Address: {address}</p>
        <h2>Names starting with vij</h2>
        {namesStartingWithVij}
        <ul>
          {namesStartingWithVij.map((item, index) => (
            <li key={`${item}-${index}`}>{item}</li>
          ))}
        </ul>
      </header>
      <Welcome name="vijaytaaa" />

      <Profile />
      <Product />
      <Hooks />
      <ThemeContext.Provider value="light">
        <div>
          <h1>Theme Button</h1>
          <ThemeButton />
        </div>
        </ThemeContext.Provider>
        <Api />
    </div>
  );
}

export default App;
